const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=id=>document.getElementById(id);
const n=(v,d=0)=>Number(v).toLocaleString('ko-KR',{minimumFractionDigits:d,maximumFractionDigits:d});
const signed=(v,d=0)=>(v>0?'+':v<0?'−':'')+n(Math.abs(v),d);
const cls=v=>v>0?'pos':v<0?'neg':'';
const grade=g=>`<span class="grade ${esc(g)}">${esc(g)}</span>`;
let view;
const shockLabel=r=>`${r.per.mode==='pct'?'+'+r.per.size+'%':'+'+r.per.size+' '+r.per.unit}`;
function renderImpact(){const key=$('window').value,stock=$('stock').value,sort=$('sort').value;
 const rows=view.rows.filter(r=>(!stock||r.stock===stock)&&r.impacts[key]&&!(r.seasonal&&key!=='yoy'&&$('hide-seasonal').checked)).map(r=>({r,t:r.impacts[key],w:view.indicators[r.indicator].windows[key],ind:view.indicators[r.indicator]}));
 rows.sort((a,b)=>sort==='abs'?Math.abs(b.t.value)-Math.abs(a.t.value):Math.abs(b.t.pctOfOp??0)-Math.abs(a.t.pctOfOp??0));
 const max=Math.max(1,...rows.map(x=>Math.abs(x.t.pctOfOp??0)));
 $('impact').innerHTML=rows.length?'<table><thead><tr><th>종목</th><th>지표</th><th>변동 (기준일→최신)</th><th>연간 이익 환산(억원)</th><th>범위</th><th>영업이익 대비</th><th>이익 기준 · 시차</th></tr></thead><tbody>'+rows.map(({r,t,w,ind})=>`<tr><td><b>${esc(r.stockName)}</b></td><td>${esc(r.indicatorName)}${r.seasonal&&key!=='yoy'?'<br><small class="neg">계절성 큼 · 전년 동기 기준 권장</small>':''}</td><td class="num">${n(w.base,2)} → ${n(ind.latest.value,2)} ${esc(ind.unit)}<br><small>${esc(w.from)} → ${esc(ind.latest.date)} · ${signed(w.abs,2)}${w.pct!=null?' ('+signed(w.pct,1)+'%)':''}</small></td><td class="num ${cls(t.value)}"><b>${signed(t.value,Math.abs(t.value)<10?1:0)}</b>${grade(r.grade)}</td><td class="num">${t.low!=null?signed(t.low)+' ~ '+signed(t.high):'–'}</td><td class="num ${cls(t.value)}">${t.pctOfOp!=null?signed(t.pctOfOp,2)+'%':'–'}<span class="bar ${cls(t.value)}" style="width:${Math.round(Math.abs(t.pctOfOp??0)/max*80)}px"></span></td><td>${esc(r.metric)}<br><small>${esc(r.lag)}</small></td></tr>`).join('')+'</tbody></table>':'<p class="muted">이 기간에 비교 가능한 관측값이 없습니다.</p>';}
function renderWhatIf(){const ids=[...new Set(view.rows.map(r=>r.indicator))];const vals=Object.fromEntries(ids.map(id=>[id,Number($('wi-'+id)?.value)||0]));const by={};
 for(const r of view.rows){const d=vals[r.indicator];if(!d)continue;const ind=view.indicators[r.indicator];let k;if(r.per.mode==='pct'){if(!ind.latest?.value)continue;k=(d/ind.latest.value*100)/r.per.size;}else k=d/r.per.size;(by[r.stock]??=[]).push({r,v:r.op*k});}
 const rows=Object.entries(by).map(([code,list])=>({code,list,total:list.reduce((a,x)=>a+x.v,0)})).sort((a,b)=>Math.abs(b.total/(view.opBase[b.code]?.op||1e9))-Math.abs(a.total/(view.opBase[a.code]?.op||1e9)));
 $('whatif').innerHTML=rows.length?'<table><thead><tr><th>종목</th><th>합계(억원/년)</th><th>기준 영업이익</th><th>대비 %</th><th>내역</th></tr></thead><tbody>'+rows.map(x=>{const b=view.opBase[x.code];return `<tr><td><b>${esc(view.stocks[x.code])}</b></td><td class="num ${cls(x.total)}"><b>${signed(x.total)}</b></td><td class="num">${b?n(b.op)+' ('+esc(b.fy)+')':'–'}</td><td class="num ${cls(x.total)}">${b?signed(x.total/b.op*100,2)+'%':'–'}</td><td>${x.list.map(i=>`${esc(i.r.indicatorName)} ${signed(i.v)}${grade(i.r.grade)}`).join(' · ')}</td></tr>`;}).join('')+'</tbody></table>':'<p class="muted">변동폭을 입력하세요. 예: 원/달러 +20, Dubai +5.</p>';}
function renderMatrix(){const ids=[...new Set(view.rows.map(r=>r.indicator))],codes=Object.keys(view.stocks);
 $('matrix').innerHTML='<table><thead><tr><th>종목<br><small>기준 영업이익</small></th>'+ids.map(id=>{const r=view.rows.find(x=>x.indicator===id);return `<th>${esc(view.indicators[id].name)}<br><small>${esc(shockLabel(r))}</small></th>`;}).join('')+'</tr></thead><tbody>'+codes.map(code=>{const b=view.opBase[code];return `<tr><td><b>${esc(view.stocks[code])}</b><br><small>${b?n(b.op)+'억 · '+esc(b.fy):''}</small></td>`+ids.map(id=>{const r=view.rows.find(x=>x.indicator===id&&x.stock===code);if(!r){const gap=view.gaps.some(g=>g.indicator===id&&g.stock===code);return `<td class="cell"><small>${gap?'·':''}</small></td>`;}const same=view.rows.find(x=>x.indicator===id).per.size===r.per.size&&view.rows.find(x=>x.indicator===id).per.mode===r.per.mode;return `<td class="cell ${cls(r.op)}" title="${esc(r.metric+' · '+r.lag)}"><b>${signed(r.op,Math.abs(r.op)<10?1:0)}</b>${grade(r.grade)}<br><small>${r.unitPctOfOp!=null?signed(r.unitPctOfOp,2)+'%':''}${same?'':' · '+esc(shockLabel(r))+' 기준'}</small></td>`;}).join('')+'</tr>';}).join('')+'</tbody></table>';}
function renderEvidence(){$('evidence').innerHTML='<table><thead><tr><th>종목 · 지표</th><th>단위 충격 → 영향</th><th>조건 · 한계</th><th>출처</th></tr></thead><tbody>'+view.rows.map(r=>`<tr><td><b>${esc(r.stockName)}</b><br>${esc(r.indicatorName)}</td><td class="num ${cls(r.op)}">${esc(shockLabel(r))}<br><b>${signed(r.op,Math.abs(r.op)<10?1:0)}억</b>${grade(r.grade)}${r.range?`<br><small>${signed(r.range[0])} ~ ${signed(r.range[1])}</small>`:''}<br><small>${esc(r.metric)}</small></td><td>${esc(r.note)}<br><small>시차: ${esc(r.lag)}</small></td><td><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.source)} ↗</a><br><small>${esc(r.asOf)}</small></td></tr>`).join('')+'</tbody></table>';
 const byInd={};for(const g of view.gaps)(byInd[g.indicatorName]??=[]).push(g.stockName);$('gap-count').textContent=view.gaps.length+'쌍';$('gaps').innerHTML=Object.entries(byInd).map(([k,v])=>`<div><b>${esc(k)}</b>: ${esc(v.join(' · '))}</div>`).join('');}
async function load(){const r=await fetch('/api/sensitivity');if(!r.ok)throw Error('민감도 자료 읽기 실패');view=await r.json();
 $('asof').textContent=`민감도 자료 점검일 ${view.dataAsOf} · 정량 확보 ${view.rows.length}쌍 / 미확보 ${view.gaps.length}쌍 · 가격은 대시보드 최신 관측값`;$('assumption').textContent=view.assumption;
 $('window').innerHTML=view.windows.map(w=>`<option value="${w.key}"${w.key==='d7'?' selected':''}>${esc(w.label)}</option>`).join('');
 $('stock').innerHTML+=Object.entries(view.stocks).filter(([c])=>view.rows.some(r=>r.stock===c)).map(([c,nm])=>`<option value="${c}">${esc(nm)}</option>`).join('');
 const ids=[...new Set(view.rows.map(r=>r.indicator))];$('whatif-inputs').innerHTML=ids.map(id=>{const i=view.indicators[id];return `<label>${esc(i.name)} 변동 (${esc(i.unit)})<input type="number" step="any" id="wi-${id}" placeholder="0"><small>현재 ${i.latest?n(i.latest.value,2)+' · '+esc(i.latest.date):'관측 없음'}</small></label>`;}).join('');
 for(const id of ['window','stock','sort','hide-seasonal'])$(id).addEventListener('change',renderImpact);$('whatif-inputs').addEventListener('input',renderWhatIf);
 renderImpact();renderWhatIf();renderMatrix();renderEvidence();}
load().catch(e=>{$('asof').textContent=e.message;});
